<?php
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');if($title!==''){db()->prepare('INSERT INTO tasks(title,description,task_date,priority) VALUES(?,?,?,?)')->execute([$title,trim($_POST['description']??''),$_POST['task_date']?:date('Y-m-d'),$_POST['priority']??'medium']);flash('Task added to your planner.');}redirect('index.php?page=planner');}
if(isset($_GET['done'])){db()->prepare("UPDATE tasks SET status='completed',completed_at=NOW() WHERE id=?")->execute([(int)$_GET['done']]);flash('Task completed.');redirect('index.php?page=planner');}
$rows=db()->query('SELECT * FROM tasks ORDER BY task_date,FIELD(priority,"high","medium","low")')->fetchAll();
?><div class="page-heading"><div><p class="eyebrow">MAKE TIME FOR LEARNING</p><h1>Study Planner</h1><p class="muted">Plan your study sessions and track daily commitments.</p></div></div><div class="two-col"><section class="card"><h2>Add a study task</h2><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Task</label><input name="title" required><label>Details</label><textarea name="description"></textarea><label>Date</label><input type="date" name="task_date" value="<?=date('Y-m-d')?>"><label>Priority</label><select name="priority"><option value="high">High</option><option value="medium" selected>Medium</option><option value="low">Low</option></select><button class="btn primary">Add task</button></form></section><section class="card"><h2>Study schedule</h2><?php if(!$rows):?><div class="empty-state compact">Your planner is empty.</div><?php else:foreach($rows as $t):?><div class="list-item"><div class="grow"><b><?=e($t['title'])?></b><small><?=e($t['task_date'])?> · <?=e($t['priority'])?></small><small><?=e($t['description']??'')?></small></div><?php if($t['status']==='active'):?><a class="btn small secondary" href="index.php?page=planner&done=<?=$t['id']?>">Done</a><?php else:?><span class="pill success">Done</span><?php endif;?></div><?php endforeach;endif;?></section></div>
